package com.arteon.geocam; import org.junit.Test; import static org.junit.Assert.*; public class CaptureEvidenceLinkTest { private CaptureEvidenceLink fresh(){CaptureEvidenceLink x=new CaptureEvidenceLink();x.begin("a");return x;} @Test public void resultFirst(){CaptureEvidenceLink x=fresh();x.result("a",100,1);assertEquals("WAITING_IMAGE",x.status("a"));x.image("a",100);assertEquals("TIMESTAMP_MATCHED",x.status("a"));} @Test public void imageFirst(){CaptureEvidenceLink x=fresh();x.image("a",100);assertEquals("WAITING_RESULT",x.status("a"));x.result("a",100,1);assertEquals("TIMESTAMP_MATCHED",x.status("a"));} @Test public void wrongTimestampNeverMatches(){CaptureEvidenceLink x=fresh();x.image("a",100);x.result("a",101,1);assertEquals("TIMESTAMP_MISMATCH",x.status("a"));} @Test public void repeatedCallbackIsIdempotent(){CaptureEvidenceLink x=fresh();x.image("a",100);x.result("a",100,1);x.result("a",100,1);assertEquals("TIMESTAMP_MATCHED",x.status("a"));} @Test public void twoFramesAtSameTimeAreAmbiguous(){CaptureEvidenceLink x=fresh();x.image("a",100);x.result("a",100,1);x.result("a",100,2);assertEquals("AMBIGUOUS_RESULT",x.status("a"));} @Test public void oldCaptureCannotContaminateNext(){CaptureEvidenceLink x=fresh();x.image("a",100);x.begin("b");x.result("a",100,1);x.image("b",100);assertEquals("WAITING_RESULT",x.status("b"));assertEquals("STALE_CAPTURE",x.status("a"));} @Test public void cancelledCaptureRejectsLateCallbacks(){CaptureEvidenceLink x=fresh();x.cancel("a");x.image("a",100);x.result("a",100,1);assertEquals("CLOSED_UNVERIFIED",x.status("a"));} @Test public void missingTimestampIsNotSuccess(){CaptureEvidenceLink x=fresh();x.image("a",0);x.result("a",100,1);assertEquals("INVALID_OR_OVERFLOW",x.status("a"));} @Test public void conflictingImagesAreRejected(){CaptureEvidenceLink x=fresh();x.image("a",100);x.image("a",101);x.result("a",100,1);assertEquals("INVALID_OR_OVERFLOW",x.status("a"));} @Test public void boundedMemoryFailsClosed(){CaptureEvidenceLink x=fresh();x.image("a",100);for(int i=0;i<9;i++)x.result("a",100+i,i);assertEquals("INVALID_OR_OVERFLOW",x.status("a"));} }